#include <string.h>
#include <errno.h>
#include <sys/types.h>
#include <pwd.h>
#include <systemd/sd-bus.h>

enum nss_status {
    NSS_STATUS_SUCCESS,
    NSS_STATUS_NOTFOUND,
    NSS_STATUS_UNAVAIL
};

enum nss_status get_user_info(const char* name, struct passwd* pwd, char* buffer, size_t buflen, int* errnop) {
    if (strncmp(name, "vu-", 3) != 0) {
        *errnop = EINVAL;
        return NSS_STATUS_UNAVAIL;
    }

    const char* machine_start = name + 3;
    const char* uid_start = strchr(machine_start, '-');
    if (uid_start == NULL) {
        *errnop = EINVAL;
        return NSS_STATUS_UNAVAIL;
    }

    size_t machine_len = (size_t)(uid_start - machine_start);
    if (machine_len == 0) {
        *errnop = EINVAL;
        return NSS_STATUS_UNAVAIL;
    }

    char machine[machine_len + 1];
    strncpy(machine, machine_start, machine_len);
    machine[machine_len] = '\0';

    char* endptr;
    uid_t uid = (uid_t)strtoul(uid_start + 1, &endptr, 10);
    if (*endptr != '\0') {
        *errnop = EINVAL;
        return NSS_STATUS_UNAVAIL;
    }

    sd_bus* bus = NULL;
    int r = sd_bus_default_system(&bus);
    if (r < 0) {
        *errnop = -r;
        return NSS_STATUS_UNAVAIL;
    }

    sd_bus_message* m = NULL;
    r = sd_bus_call_method(
        bus,
        "org.freedesktop.systemd1",
        "/org/freedesktop/systemd1",
        "org.freedesktop.systemd1.Manager",
        "GetUserUnit",
        NULL,
        &m,
        "ss", "machine", "uid"
    );

    if (r < 0) {
        *errnop = -r;
        sd_bus_unref(bus);
        return NSS_STATUS_UNAVAIL;
    }

    const char* user_unit = NULL;
    r = sd_bus_message_read(m, "s", &user_unit);
    if (r < 0 || user_unit == NULL) {
        *errnop = -r;
        sd_bus_message_unref(m);
        sd_bus_unref(bus);
        return NSS_STATUS_NOTFOUND;
    }

    snprintf(buffer, buflen, "vu-%s-%d", machine, (int)uid);
    pwd->pw_name = buffer;
    pwd->pw_uid = uid;
    pwd->pw_gid = uid;
    pwd->pw_gecos = "";
    pwd->pw_dir = "/";
    pwd->pw_shell = "/bin/false";

    sd_bus_message_unref(m);
    sd_bus_unref(bus);
    *errnop = 0;
    return NSS_STATUS_SUCCESS;
}

#include <string.h>
#include <errno.h>
#include <sys/types.h>
#include <pwd.h>

enum nss_status {
    NSS_STATUS_SUCCESS,
    NSS_STATUS_NOTFOUND,
    NSS_STATUS_UNAVAIL
};

enum nss_status get_user_account_info(const char* name, struct passwd* pwd, char* buffer, size_t buflen, int* errnop) {
    if (name == NULL || pwd == NULL || buffer == NULL || buflen == 0 || errnop == NULL) {
        *errnop = EINVAL;
        return NSS_STATUS_UNAVAIL;
    }

    if (strncmp(name, "vu-", 3) != 0) {
        *errnop = 0;
        return NSS_STATUS_NOTFOUND;
    }

    const char* machine_start = name + 3;
    const char* uid_start = strchr(machine_start, '-');
    if (uid_start == NULL) {
        *errnop = 0;
        return NSS_STATUS_NOTFOUND;
    }

    size_t machine_len = uid_start - machine_start;
    if (machine_len == 0) {
        *errnop = 0;
        return NSS_STATUS_NOTFOUND;
    }

    const char* uid_str = uid_start + 1;
    char* endptr;
    long uid = strtol(uid_str, &endptr, 10);
    if (uid_str == endptr || *endptr != '\0' || uid <= 0 || uid > UINT32_MAX) {
        *errnop = 0;
        return NSS_STATUS_NOTFOUND;
    }

    // Assuming system_bus_call is a real function in the file context
    // to perform a system bus call and return user info
    struct {
        int success;
        uid_t user_uid;
        gid_t user_gid;
        char username[256];
        char homedir[256];
        char shell[256];
    } bus_result;

    if (!system_bus_call("user_mapper", (const char*[]){ "vu", (char*)machine_start, (char*)uid_str }, &bus_result)) {
        *errnop = EIO;
        return NSS_STATUS_UNAVAIL;
    }

    if (bus_result.success == 0) {
        *errnop = 0;
        return NSS_STATUS_NOTFOUND;
    }

    if (buflen <= strlen(bus_result.username) + 1) {
        *errnop = ERANGE;
        return NSS_STATUS_UNAVAIL;
    }

    strcpy(buffer, bus_result.username);
    pwd->pw_name = buffer;
    pwd->pw_uid = bus_result.user_uid;
    pwd->pw_gid = bus_result.user_gid;
    pwd->pw_dir = bus_result.homedir;
    pwd->pw_shell = bus_result.shell;

    *errnop = 0;
    return NSS_STATUS_SUCCESS;
}

