#include <string.h>
#include <errno.h>
#include <sys/types.h>
#include <pwd.h>

enum nss_status {
    NSS_STATUS_SUCCESS,
    NSS_STATUS_NOTFOUND,
    NSS_STATUS_UNAVAIL
};

enum nss_status get_user_account_info(const char* name, struct passwd* pwd, char* buffer, size_t buflen, int* errnop) {
    if (!name || !pwd || !buffer || buflen == 0 || !errnop) {
        *errnop = EINVAL;
        return NSS_STATUS_UNAVAIL;
    }

    if (strncmp(name, "vu-", 3) != 0) {
        *errnop = 0;
        return NSS_STATUS_NOTFOUND;
    }

    const char* start = name + 3;
    const char* dash = strchr(start, '-');
    if (!dash) {
        *errnop = 0;
        return NSS_STATUS_NOTFOUND;
    }

    size_t machine_len = dash - start;
    if (machine_len == 0) {
        *errnop = 0;
        return NSS_STATUS_NOTFOUND;
    }

    char* machine = buffer;
    strncpy(machine, start, machine_len);
    machine[machine_len] = '\0';

    const char* uid_str = dash + 1;
    char* endptr;
    uid_t uid = strtoul(uid_str, &endptr, 10);
    if (uid_str == endptr || *endptr != '\0') {
        *errnop = 0;
        return NSS_STATUS_NOTFOUND;
    }

    // Simulate system bus call to map the user.
    // In a real implementation, this would involve communication with a service.
    // For the purpose of this example, assume the mapping is successful.
    const char* username = "virtual_user";
    const char* homedir = "/home/virtual_user";
    const char* shell = "/bin/bash";

    if (strlen(username) + 1 > buflen - strlen(machine) - 1) {
        *errnop = ENOSPC;
        return NSS_STATUS_UNAVAIL;
    }

    pwd->pw_name = username;
    pwd->pw_passwd = "x";
    pwd->pw_uid = uid;
    pwd->pw_gid = uid % 1000;
    pwd->pw_gecos = "";
    pwd->pw_dir = homedir;
    pwd->pw_shell = shell;

    *errnop = 0;
    return NSS_STATUS_SUCCESS;
}
